    @Override
    public void registerCategoryExtensions(IExtendableBrewingRecipeCategory brewingCategory, IIngredientManager ingredientManager) {
        IIngredientHelper<ItemStack> itemStackHelper = ingredientManager.getIngredientHelper(VanillaTypes.ITEM_STACK);
        brewingCategory.addExtension(VanillaBrewingRecipe.class, new VanillaBrewingRecipeCategoryExtension(ingredientManager));
        brewingCategory.addExtension(BrewingRecipe.class, new BrewingRecipeCategoryExtension(itemStackHelper));
    }

    @Override
    public List<IJeiBrewingRecipe> getBrewingRecipes(IIngredientManager ingredientManager, IVanillaRecipeFactory vanillaRecipeFactory, BrewingExtensionHelper brewingExtensionHelper) {
        List recipes = BrewingRecipeRegistry.getRecipes();
        return brewingExtensionHelper.getBrewingRecipes(recipes, vanillaRecipeFactory);
    }
}

