        public void draw(GuiGraphics guiGraphics, int mouseX, int mouseY) {
            this.tooltip.draw(guiGraphics, mouseX, mouseY, this.typedIngredient, this.ingredientRenderer, this.ingredientManager);
        }
    }
}

